function buildTutorialSteps(source) {
  const sourceSteps = source === "novelai" ? NOVELAI_STEPS : COMFYUI_STEPS;
  return [TUTORIAL_SELECTION_STEP, IMAGE_SOURCE_STEP, ...sourceSteps, ...SHARED_STEPS];
}

