async function extractNovelAIJsonImages(response) {
  try {
    const json = await response.json();
    const images = [];
    for (const item of json.images ?? []) {
      if (item.image) images.push(decodeBase64Image(item.image));
    }
    if (!images.length) throw new Error("JSON 响应中没有找到图片数据");
    return images;
  } catch (error) {
    throw new Error(`[JSON 解析] ${error.message}`);
  }
}
function decodeBase64Image(base64) {
  const binary = atob(base64);
  const bytes = Uint8Array.from(binary, (character) => character.charCodeAt(0));
  return new Blob([bytes], { type: "image/png" });
}

const IMAGE_TYPES = {
  png: "image/png",
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
  webp: "image/webp"
};
async function extractImages(zipBlob) {
  const zip = await JSZip.loadAsync(zipBlob);
  const entries = Object.values(zip.files).filter((file) => !file.dir && isImageName(file.name));
  if (!entries.length) throw new Error("官方响应中没有找到图片");
  return Promise.all(entries.map(async (entry) => {
    const data = await entry.async("blob");
    return new Blob([data], { type: getImageType(entry.name) });
  }));
}
function isImageName(name) {
  return Object.keys(IMAGE_TYPES).some((ext) => name.toLowerCase().endsWith(`.${ext}`));
}
function getImageType(name) {
  const ext = name.toLowerCase().split(".").pop() ?? "png";
  return IMAGE_TYPES[ext] ?? "image/png";
}

